using System;
using System.Linq;
namespace StickyNotes;
internal static class GoogleLoginPage {
 internal static string Html(bool success){string message=success?"Volte ao Sticky Notes para confirmar a conta e ativar a sincronização.":"Não foi possível concluir o login. Volte ao aplicativo para tentar novamente.";string encoded=string.Concat(message.Select(c=>c>127?"&#"+(int)c+";":c.ToString()));return "<!doctype html><html lang=pt-BR><meta charset=utf-8><meta name=viewport content='width=device-width, initial-scale=1'><title>SMT Sticky Notes</title><style>body{margin:0;background:#f3f3f3;color:#1a1a1a;font:16px 'Segoe UI',sans-serif;display:grid;place-items:center;min-height:100vh}main{max-width:440px;margin:24px;padding:32px;background:#fff;border:1px solid #ddd;border-radius:12px;box-shadow:0 8px 24px #0001}h1{font-size:24px;margin:0 0 16px}p{line-height:1.6;margin:0}main:before{content:\">\";display:block;font-size:28px;margin-bottom:16px;color:#0f6cbd}@media(prefers-color-scheme:dark){body{background:#202020;color:#fff}main{background:#292929;border-color:#444}}</style><main><h1>SMT Sticky Notes</h1><p>"+encoded+"</p></main><script>history.replaceState(null,'','/connected')</script></html>";}
}
